+    push_floats(&mut out, &r.photo.heat_erg_per_absorber_s);
+    push_floats(&mut out, &r.absorbed_per_h);
+    push_floats(&mut out, &[r.binding_ev_per_h, r.heat_ev_per_h]);
+    for xs in [
+        &r.state.number,
+        &r.state.energy_ref,
+        &r.state.support_lo,
+        &r.state.support_hi,
