+        &s.photons,
+        &s.photon_energy_ref,
+        &s.photon_support_lo,
+        &s.photon_support_hi,
+        &s.photon_inactive_number,
+        &s.photon_inactive_energy_ref,
+    ] {
+        out.push(xs.len() as u64);
+        push_floats(&mut out, xs);
+    }
