+fn absorption_words(p: &PreparedAbsorption, r: &AbsorptionResult) -> Vec<u64> {
+    let mut out = vec![p.node_count() as u64];
+    let q = p.diagnostics;
+    push_floats(
+        &mut out,
+        &[
