+fn require_equal(label: &str, a: &[u64], b: &[u64]) -> Result<()> {
+    if a != b {
+        let first = a
+            .iter()
+            .zip(b)
+            .position(|(x, y)| x != y)
+            .unwrap_or(a.len().min(b.len()));
+        return Err(format!(
+            "HPC_BITWISE_MISMATCH {label} first_word={first} lengths={}/{}",
+            a.len(),
+            b.len()
+        )
+        .into());
+    }
+    Ok(())
+}
+
+fn words_json(xs: &[u64]) -> String {
+    format!(
+        "[{}]",
+        xs.iter()
+            .map(|x| format!("\"{x:016x}\""))
+            .collect::<Vec<_>>()
+            .join(",")
+    )
+}
+
+fn checksum(xs: &[u64]) -> String {
+    // A compact non-cryptographic aid; complete words are also preserved.
+    let mut value = 0xcbf29ce484222325_u64;
+    for x in xs {
+        for byte in x.to_le_bytes() {
+            value ^= u64::from(byte);
+            value = value.wrapping_mul(0x100000001b3);
+        }
+    }
+    format!("{value:016x}")
+}
+
+fn quoted(s: &str) -> String {
+    let mut out = String::from("\"");
+    for c in s.chars() {
+        match c {
+            '"' => out.push_str("\\\""),
+            '\\' => out.push_str("\\\\"),
+            '\n' => out.push_str("\\n"),
+            '\r' => out.push_str("\\r"),
+            '\t' => out.push_str("\\t"),
+            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
+            c => out.push(c),
+        }
+    }
+    out.push('"');
+    out
+}
