+/// the caller owns H/He reactions, photon transport, free-free, CMB and FLRW.
+pub fn d_atomic_rhs(
+    provider: DAtomicProvider,
+    state: &IsotopeNumberState,
+    temperature_k: f64,
+    photo: &DPhotoInput,
+    cx: DChargeExchange,
