+            thermal: -ci_chemical,
+            chemical: ci_chemical,
+            ..DEnergyLedger::default()
+        },
+        DEnergyLedger {
+            thermal: -rr_kinetic,
+            chemical: -rr_chemical_loss,
+            escape: arithmetic(rr_kinetic + rr_chemical_loss)?,
+            photon_input: 0.0,
+        },
+        DEnergyLedger {
+            thermal: -ce,
+            escape: ce,
+            ..DEnergyLedger::default()
+        },
+        DEnergyLedger {
+            thermal: -cxf_defect,
+            chemical: cxf_defect,
+            ..DEnergyLedger::default()
+        },
+        DEnergyLedger {
+            thermal: cxr_defect,
+            chemical: -cxr_defect,
+            ..DEnergyLedger::default()
+        },
+    ];
