+fn cell(c: &CovariantTransport, lo: f64, hi: f64, mean: f64) -> PhotonState {
+    let mut p = c.empty_state();
+    p.number[0] = 1.0;
+    p.energy_ref[0] = mean;
+    p.support_lo[0] = lo;
+    p.support_hi[0] = hi;
+    c.validate_state(&p).unwrap();
+    p
