+#[test]
+fn partition_empty_below_above_and_exact_threshold_delta() {
+    let c = core();
+    let empty = c.empty_state();
+    let e = c.partition_below_hi(&empty, &g(0.05)).unwrap();
+    assert_eq!(e.active, empty);
