+fn polynomial(x: [f64; 4]) -> [f64; 4] {
+    [
+        x[0] * x[0] + x[1],
+        x[1] * 3.0 + x[2],
+        x[2] * x[2] - x[3],
+        x[3] * 2.0 + x[0],
+    ]
