+fn conserved(step: DhStep) {
+    let a = step.totals_before;
+    let b = step.totals_after;
+    for (x, y) in [
+        (a.hydrogen_m3, b.hydrogen_m3),
+        (a.deuterium_m3, b.deuterium_m3),
+        (a.positive_charge_m3, b.positive_charge_m3),
